-- Migration: 000112_alfa_pte_practice_questions.up.sql
-- Alfa PTE Practice Questions & AI Score Compendium (100 Questions across all 20 PTE Subtasks).
-- 5 Questions per Subtask. Replay-safe via ON CONFLICT (id) DO NOTHING.

INSERT INTO reading_passages
    (id, exam_version_id, title, subtitle, paragraphs, word_count, difficulty, topic, tags, passage_slot, modules)
VALUES
    ('rp-pte-alfa-rwfib-12001335', 'pte-2026-01', 'Public Education', 'PTE Reading & Writing Fill in Blanks', '[{"label": "A", "text": "Public education is generally free. However, many schools to choose to charge parents for extra services, such as textbooks, excursions, and music lessons. Low-income families may not be able to afford these costs, which puts their children at a disadvantage, especially when accessing information."}]'::jsonb, 0, 'medium', 'Academic Reading', ARRAY['PTE', 'Alfa PTE', 'Reading'], 'custom', ARRAY['academic']),
    ('rp-pte-alfa-rwfib-12001334', 'pte-2026-01', 'Resultant Force', 'PTE Reading & Writing Fill in Blanks', '[{"label": "A", "text": "The overall result of two or more forces acting on an object is called the resultant force. The resultant of two forces is a single force, which has the same effect as the two forces combined. If two forces pull an object in opposite directions, the size of the resultant can be found by subtracting one force from the other. If the forces are equal, they balance each other."}]'::jsonb, 0, 'medium', 'Academic Reading', ARRAY['PTE', 'Alfa PTE', 'Reading'], 'custom', ARRAY['academic']),
    ('rp-pte-alfa-rwfib-12001333', 'pte-2026-01', 'Dogs & Humans', 'PTE Reading & Writing Fill in Blanks', '[{"label": "A", "text": "Dogs, the first domestic animals, evolved from East Asian wolves approximately 20,000-40,000 years ago. Dogs understand human body language, many spoken words, and even abstract symbols. Dogs pay attention to human faces and eyes, and they often turn to humans to help solve problems. Dogs and humans form a mutual emotional bond that reduces stress in both species. Being around dogs improve human physical and mental well-being. Most dogs are very social and play with other dogs if they can. Stray and feral dogs are common on the edges of human society. They form social groups, and sometimes cooperate in territorial defense, much as wolves do."}]'::jsonb, 0, 'medium', 'Academic Reading', ARRAY['PTE', 'Alfa PTE', 'Reading'], 'custom', ARRAY['academic']),
    ('rp-pte-alfa-rwfib-12001332', 'pte-2026-01', 'Learning', 'PTE Reading & Writing Fill in Blanks', '[{"label": "A", "text": "Learning to ride a bicycle as an adult can be challenging, especially for a beginner. A trained instructor can guide learners through basic techniques and help them feel more comfortable on the road. The purpose is not to become a professional rider immediately, but to build balance and confidence. Even an amateur can improve with regular practice. Later, some learners may join outdoor events or friendly competitions."}]'::jsonb, 0, 'medium', 'Academic Reading', ARRAY['PTE', 'Alfa PTE', 'Reading'], 'custom', ARRAY['academic']),
    ('rp-pte-alfa-rwfib-12001331', 'pte-2026-01', 'Charity Group', 'PTE Reading & Writing Fill in Blanks', '[{"label": "A", "text": "Landing a position with the acclaimed charity group, often referred to as the angel providers, was a dream come true for Sarah. Although the organization could only offer a meager stipend, she eagerly accepted the terms. She believed that working alongside such selfless individuals was far more rewarding than chasing a high corporate salary. Over the years, this dedicated group has continued to provide essential healthcare to impoverished communities worldwide, relying heavily on passionate workers who value purpose over financial gain."}]'::jsonb, 0, 'medium', 'Academic Reading', ARRAY['PTE', 'Alfa PTE', 'Reading'], 'custom', ARRAY['academic']),
    ('rp-pte-alfa-rmcma-9000198', 'pte-2026-01', 'Job Opening', 'PTE Multiple Choice (Multiple)', '[{"label": "A", "text": "Job description: driving a company car as required, between branches in Canada and occasionally in the United States\nThis position requires a responsible person with the following:\n. a valid Canadian driver''s licence\n. a valid passport and be able to cross over into the United States for training\n. driving experience, such as delivery driver, Uber, taxi, etc\n. Availability to work in locations out of town\n. No speeding tickets or fines\nWe provide:\n. Paid training is 2 days starting immediately !!!\n. Food expenses for out of province trips are also included\n. Hotel expenses are covered\n. Hours are full-time (approx. 8-10 hours per day)\n. Company car and gas costs are covered\n. Weekly pay every Friday (salary : $17.00 /hour)\n. 4% Vacation Pay included\n. Permanent hire with benefits possible upon job performance (to be discussed\nafter two months)\n. Travel to the United States for 2 days for paid training"}]'::jsonb, 0, 'medium', 'Academic Reading', ARRAY['PTE', 'Alfa PTE', 'Reading'], 'custom', ARRAY['academic']),
    ('rp-pte-alfa-rmcma-9000197', 'pte-2026-01', 'Disciplined Inquiry', 'PTE Multiple Choice (Multiple)', '[{"label": "A", "text": "The steps in the scientific method guide researchers in planning, conducting, and interpreting research studies. However, it is\nessential to recognize some of the limitations of such a \"disciplined inquiry \" approach. For example, it cannot provide answers to\nquestions that seek to determine what should be done. Some questions are not answerable through research studies because\ncollecting data will not resolve them, or because personal philosophical values and ethics also influence the answers. Secondly,\nresearch studies can never capture the full richness of the individuals and sites that they study. Although some research approaches\nlead to a deeper understanding of the research context than others, no approach provides full comprehension of a site and its\ninhabitants. No matter how many variables one studies or how long one is immersed in a research context, there will always be\nother variables and aspects of a context that were not examined. Thus, all research gives us a Simplified version of reality, an\nabstraction from the whole. Thirdly, there are limits to our research technologies. Our data collection instruments and available\ntheories are primitive compared to those of, say, medicine. Our measuring instruments always have some degree of Error. The\nvariables we study are often proxies for the real behavior we seek to examine. For example, we use a multiple-choice test to assess\na person''s values. Finally educational research is carried out the co-operation of participants who Agree to provide researchers with\ndata. Because researchers deal with human beings, they must consider a number of ethical concerns and responsibilities to the\nparticipants. For example, they must shelter participants from real or potential harm. They must inform participants about the nature\nof the planned research and address their expectations."}]'::jsonb, 0, 'medium', 'Academic Reading', ARRAY['PTE', 'Alfa PTE', 'Reading'], 'custom', ARRAY['academic']),
    ('rp-pte-alfa-rmcma-9000196', 'pte-2026-01', 'Migration', 'PTE Multiple Choice (Multiple)', '[{"label": "A", "text": "No one may yet be advocating it, but two recent reports from the IMF suggest one possible solution to many of the emerging world''s\neconomic woes: mass migration from Africa to Asia. The Fund''s latest Asia Pacific regional economic outlook, released this month,\nwarned that the continent was in danger of growing old before it became rich due to plunging birth rates. These threats leave it in far\nworse shape than the developed world, which at least became wealthy before the wrinkles set in. In sharp contrast a study of Africa\nreleased in April conclusion that a key reason Why the continent has been unable to copy Asia''s rise out of poverty is its sluggish\npace of demographic transition,\" ie that its birth rate remains far too high. In theory, a straightforward solution to both problems\nwould be a large-scale eastward shift of younger people, even if the complexities and difficulties associated with such an endeavour\nmake it virtually impossible to envisage."}]'::jsonb, 0, 'medium', 'Academic Reading', ARRAY['PTE', 'Alfa PTE', 'Reading'], 'custom', ARRAY['academic']),
    ('rp-pte-alfa-rmcma-9000195', 'pte-2026-01', 'Genome', 'PTE Multiple Choice (Multiple)', '[{"label": "A", "text": "Imagine visiting your doctor for an annual exam, only this time the checkup begins not with a physical but with a routine sequencing\nof your genome. Using information from the test, your physician not only diagnoses the diseases you are most susceptible to but\nalso selects the types and doses of medication best suited to help you combat the maladies. It''s called personalized medicine. And\nno, it doesn''t mean your doctor will be extra kind or personable. The term broadly refers to the detection, treatment, and prevention\nof diseases based on a person''s unique genetic makeup, and many people believe it will revolutionize health care. When you go to\nyour physician ten years from now, virtually all of the decisions about diagnosis and treatment will be based on individual information\nabout your particular circumstance as opposed to a more general kind of approach to lots of other people in your general\ncircumstance,\" said genome expert Francis Collins. Collins led the international effort to sequence the human genome, which was\ncompleted in 2003. The creation of a map of human genetic variation followed that effort. The genome contains tens of thousands of\ngenes, which code for proteins and other molecules that make life possible. Although there are some three billion \"letters\" in the\nhuman DNA code, 99.9 percent are identical between any two people. The remaining small differences hold clues about why people\ntend to develop certain diseases. We now have the technology to assess in people with disease versus those who don''t have the\ndisease, which of those genetic variances seem to be overrepresented?\" Collins said. We are on the brink of discovering what the\nhereditary factors are in diabetes, heart disease, common cancers, high blood pressure, asthma, mental illness, and virtually any\ndisease you can think of that tends to run in families."}]'::jsonb, 0, 'medium', 'Academic Reading', ARRAY['PTE', 'Alfa PTE', 'Reading'], 'custom', ARRAY['academic']),
    ('rp-pte-alfa-rmcma-9000194', 'pte-2026-01', 'Attention', 'PTE Multiple Choice (Multiple)', '[{"label": "A", "text": "Attention is a limited resource and is not an all-or-nothing response: the more attention devoted to one aspect of the environment,\nthe less is available for others. A number of experiments have studied this in animals. In one experiment, a tone and a light are\npresented simultaneously to pigeons. The pigeons gain a reward only by choosing the correct combination of the two stimuli (e.g., a\nhigh-frequency tone together with a yellow light). The birds perform well at this task presumably by dividing attention between the\ntwo stimuli. When only one of the stimulus variations is presented at its rewarded value, discrimination improves on the variable\nstimulus, but Discrimination on the alternative stimulus worsens. These outcomes are consistent with the notion that attention is a\nlimited resource that can be more or less focused among incoming stimuli."}]'::jsonb, 0, 'medium', 'Academic Reading', ARRAY['PTE', 'Alfa PTE', 'Reading'], 'custom', ARRAY['academic']),
    ('rp-pte-alfa-rfib-11001117', 'pte-2026-01', 'Mountain Forest', 'PTE Reading Fill in Blanks (Drag & Drop)', '[{"label": "A", "text": "The place had both mountains and a forest. Every year, over 3.5 million visitors come to enjoy the scenery. There are also several miles of trails that wind through the area."}]'::jsonb, 0, 'medium', 'Academic Reading', ARRAY['PTE', 'Alfa PTE', 'Reading'], 'custom', ARRAY['academic']),
    ('rp-pte-alfa-rfib-11001116', 'pte-2026-01', 'Recycling Notice', 'PTE Reading Fill in Blanks (Drag & Drop)', '[{"label": "A", "text": "Today, many companies emphasize sustainability in their operations. For example, packaging should be made from recyclable materials to ensure proper disposal. In households, using energy-efficient kitchen appliances helps reduce environmental impact."}]'::jsonb, 0, 'medium', 'Academic Reading', ARRAY['PTE', 'Alfa PTE', 'Reading'], 'custom', ARRAY['academic']),
    ('rp-pte-alfa-rfib-11001115', 'pte-2026-01', 'Asking for Leave', 'PTE Reading Fill in Blanks (Drag & Drop)', '[{"label": "A", "text": "My son is unable to attend school. On the previous night I found he was sick and now I think it is better for him not to go to school so that we can avoid infection. I believe after some rest, he will become well and will successfully pass his exam. And I am happy to help him catch up on the missed lessons."}]'::jsonb, 0, 'medium', 'Academic Reading', ARRAY['PTE', 'Alfa PTE', 'Reading'], 'custom', ARRAY['academic']),
    ('rp-pte-alfa-rfib-11001114', 'pte-2026-01', 'Lifelong Learning', 'PTE Reading Fill in Blanks (Drag & Drop)', '[{"label": "A", "text": "My grandmother may have an old body, but her mind hasn''t aged a day. She says it''s because of all the hobbies she still does, such as reading, baking, and gardening. She knows that learning should never stop. Every time you pick up a hobby, you learn new skills, new words, new techniques. Just like your body needs exercise to stay fit, your brain needs learning to stay sharp!"}]'::jsonb, 0, 'medium', 'Academic Reading', ARRAY['PTE', 'Alfa PTE', 'Reading'], 'custom', ARRAY['academic']),
    ('rp-pte-alfa-rfib-11001113', 'pte-2026-01', 'Work Preparation', 'PTE Reading Fill in Blanks (Drag & Drop)', '[{"label": "A", "text": "It''s important to arrive to work early. If your start time is 8:30 a.m., you need to be at work by then. Depending on where you work, you might have to change your clothes, turn your computer on, or do some other tasks before you''re ready to work. You should complete all of these activities by the time your workday begins."}]'::jsonb, 0, 'medium', 'Academic Reading', ARRAY['PTE', 'Alfa PTE', 'Reading'], 'custom', ARRAY['academic']),
    ('rp-pte-alfa-rmcsa-8000287', 'pte-2026-01', 'Sports Readiness', 'PTE Multiple Choice (Single)', '[{"label": "A", "text": "Children of all ages need physical activity. For many, playing organized sports (such as being part of a soccer team or taking tennis\nlessons) is a fun way to keep active. To get the most benefit out of any sport, children need certain basic skills, and some of these\nskills depend on a child''s age. If they''re not ready, children may get frustrated and not want to play at all."}]'::jsonb, 0, 'medium', 'Academic Reading', ARRAY['PTE', 'Alfa PTE', 'Reading'], 'custom', ARRAY['academic']),
    ('rp-pte-alfa-rmcsa-8000286', 'pte-2026-01', 'Knowledge', 'PTE Multiple Choice (Single)', '[{"label": "A", "text": "Knowledge never stands alone. It builds upon and plays against the knowledge of previous knowers and reporters whom scholars\ncall \"sources.\" These are not, in a scholarly paper, the source of your particular argument (you are), but rather persons or\ndocuments that help you arrive at and support your argument. They are sources of information that you interpret; of ideas that you\nsupport, criticize, or develop; of vivid language that you quote and analyze."}]'::jsonb, 0, 'medium', 'Academic Reading', ARRAY['PTE', 'Alfa PTE', 'Reading'], 'custom', ARRAY['academic']),
    ('rp-pte-alfa-rmcsa-8000285', 'pte-2026-01', 'Persistence', 'PTE Multiple Choice (Single)', '[{"label": "A", "text": "Encouraging babies to be persistent in their behavior and providing lots of stimulus can help improve their learning ability,\nresearchers have said. Many parents already use educational toys, videos, and flashcards to help their children''s budding brains\ndevelop. But the scientists in the United States found that mothers who teach their babies simple tasks and encourage their children\nto persist in doing them aid their cognitive development. Persistence appears to be a stable quality that can be measured early on,\nand both infants'' early persistence and their mother''s teaching are direct pathways to cognitive status at the start of the second\nyear,\" said Poonam Nina Bannerjee of Columbia University in New York.\nIn a study published in the journal Infant Behavior and Development, Bannerjee and Catherine Tamis-Lemonda of New York\nUniversity studied 65 mothers on low incomes living in an urban area and their babies. They observed the mothers who were told to\nteach their six-month-old babies to pull a car by string, turn the page of a book, make a noise with a squeaky toy, and to transfer a\nblock from one hand to another. When the children were 14 months old, they were taught to point to body parts and to stack blocks\nin a tower. The researchers analyzed the children''s persistence by recording their behavior after they were taught the tasks and\nused a standard testing scale to assess their memory, problem-solving, verbal, and other skills. Their findings suggest that early\nteaching has a dual function of supporting both the infants'' ability to remain on task and cognitive development."}]'::jsonb, 0, 'medium', 'Academic Reading', ARRAY['PTE', 'Alfa PTE', 'Reading'], 'custom', ARRAY['academic']),
    ('rp-pte-alfa-rmcsa-8000284', 'pte-2026-01', 'Human Development Index', 'PTE Multiple Choice (Single)', '[{"label": "A", "text": "Are you happy where you live? It''s a tricky enough question to answer on an individual, subjective level, and harder still when it\ncomes to arriving at an objective judgement. There are so many factors to take into account. Is access to healthcare more important\nthan pollution levels? Should low crime rates be counted as a higher priority than freedom of speech? Economists sometimes use a\ncountry''s per capita gross domestic product - the value of all the goods and services it produces - as an indicator of quality of life, but\nit is only a crude one. To give a more rounded picture, the UN produces an annual human development index, which assigns a\nscore to each nation based on three broad sets of indicators: health and longevity, knowledge and education, and standard of living\nmeasured by purchasing power. By these measures, the worst place to live is Niger in West Africa, where life expectancy is 44.6\nyears, 71 per cent of adults are illiterate, and 79 per cent of children don''t go to school. In the top nation, Norway people are 40\ntimes wealthier, live almost twice as long, and enjoy near universal education."}]'::jsonb, 0, 'medium', 'Academic Reading', ARRAY['PTE', 'Alfa PTE', 'Reading'], 'custom', ARRAY['academic']),
    ('rp-pte-alfa-rmcsa-8000283', 'pte-2026-01', 'Glaciers', 'PTE Multiple Choice (Single)', '[{"label": "A", "text": "During most of their lives, surge glaciers behave like normal glaciers, traveling perhaps only a couple of inches per day. However, at\nintervals of 10 to 100 years, these glaciers move forward up to 100 times faster than usual. The surge often progresses along a\nglacier like a great wave, proceeding from one section to another. Subglacial streams of meltwater pressure under the glacier might\nlift it off its bed, overcoming the friction between ice and rock, thus freeing the glacier, which rapidly slides downhill. Surging glaciers\nalso might be influenced by the climate, volcanic heat, or earthquakes. However, many of these glaciers exist in the same area as\nnormal glaciers, often almost side by side."}]'::jsonb, 0, 'medium', 'Academic Reading', ARRAY['PTE', 'Alfa PTE', 'Reading'], 'custom', ARRAY['academic'])
ON CONFLICT (id) DO NOTHING;

