    ('g-pte-alfa-rfib-11001113', 'rp-pte-alfa-rfib-11001113', 1, 'fill-in-blanks-r', 'Reading: Fill in the Blanks', 'In the text below some words are missing. Drag words from the box below to the appropriate place in the text. To undo an answer choice, drag the word back to the box below the text.', '[]'::jsonb, 'hidden', FALSE, 120),
