INSERT INTO reading_reorder_items
    (id, exam_version_id, exam, title, paragraphs, word_count, difficulty, tags, is_published)
VALUES
    ('ri-pte-alfa-ro-10001082', 'pte-2026-01', 'PTE', 'Farmland and Forest', '[{"label": "p1", "text": "Seeds sprout, producing seedlings."}, {"label": "p2", "text": "They grow into saplings, which shade the lawn below."}, {"label": "p3", "text": "The saplings will grow into big trees, and eventually a forest will form."}, {"label": "p4", "text": "Farmland can be created by clearing forests."}, {"label": "p5", "text": "If the farmland is abandoned, the process will start over again."}]'::jsonb, 44, 'medium', ARRAY['PTE', 'Alfa PTE', 'Reorder']::text[], TRUE),
    ('ri-pte-alfa-ro-10001081', 'pte-2026-01', 'PTE', 'Pest Control', '[{"label": "p1", "text": "Chemical pest control dates back 4,500 years, when the Sumerians used sulfur compounds as insecticides."}, {"label": "p2", "text": "The Rig Veda, which is about 4,000 years old, also mentions the use of poisonous plants for pest control."}, {"label": "p3", "text": "And the ancient Chinese and Egyptians are also known to have used chemical pest control."}, {"label": "p4", "text": "But it was only with the industrialization and mechanization of agriculture in the 18th and 19th centuries, and the introduction of the insecticides pyrethrum and derris that chemical pest control became the method of choice."}]'::jsonb, 84, 'medium', ARRAY['PTE', 'Alfa PTE', 'Reorder']::text[], TRUE),
    ('ri-pte-alfa-ro-10001080', 'pte-2026-01', 'PTE', 'Forest Cycle', '[{"label": "p1", "text": "Seeds sprout from the soil and gradually develop into small seedlings."}, {"label": "p2", "text": "These seedlings continue to grow and eventually become young saplings."}, {"label": "p3", "text": "The saplings grow into large trees, and over time, a forest begins to form."}, {"label": "p4", "text": "The forest may later be cleared to create farmland for agricultural use."}, {"label": "p5", "text": "If the farmland is abandoned, natural vegetation begins to return and the process starts again."}]'::jsonb, 62, 'medium', ARRAY['PTE', 'Alfa PTE', 'Reorder']::text[], TRUE),
    ('ri-pte-alfa-ro-10001079', 'pte-2026-01', 'PTE', 'Bugs', '[{"label": "p1", "text": "If the landlord refuses to deal with a bed bug infestation, the tenant can seek assistance from the government."}, {"label": "p2", "text": "Alternatively, the tenant may hire a professional exterminator directly."}, {"label": "p3", "text": "Because bed bugs are extremely difficult to eliminate, the work should be carried out by trained pest control professionals."}, {"label": "p4", "text": "If the tenant hires an exterminator independently, they should choose a reputable company and make sure the treatment is performed properly."}]'::jsonb, 68, 'medium', ARRAY['PTE', 'Alfa PTE', 'Reorder']::text[], TRUE),
    ('ri-pte-alfa-ro-10001078', 'pte-2026-01', 'PTE', 'Whale', '[{"label": "p1", "text": "Whales generally live in the water."}, {"label": "p2", "text": "However, as mammals, they must come to the surface to breathe."}, {"label": "p3", "text": "That''s why their breathing organ (blowhole) is located on the top of their heads."}, {"label": "p4", "text": "When they breathe out, they produce a spout of water vapor that looks like a fountain."}]'::jsonb, 47, 'medium', ARRAY['PTE', 'Alfa PTE', 'Reorder']::text[], TRUE)
ON CONFLICT (id) DO NOTHING;

