    ('pte-alfa-we-7000502', 'pte-2026-01', 'PTE', ARRAY['PTE']::text[], 'writing', 'write-essay', 'Write Essay', 'Remote Work', 'You will have 20 minutes to plan, write and revise an essay about the topic below. Your response will be judged on how well you develop a position, organize your ideas, present supporting details, and control the elements of standard written English. You should write 200-300 words.\n\nRemote work has become increasingly common in recent years. What are the advantages and disadvantages of this trend?', 'Remote work has become increasingly common in recent years. What are the advantages and disadvantages of this trend?', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'Write a well-structured essay of 200-300 words with clear introduction, body paragraphs, and conclusion.', 'medium', 15, ARRAY['PTE', 'Alfa PTE', 'Writing']::text[], TRUE, 0, 1200, NULL, NULL, 0, NULL),
